#!/usr/bin/env python3
"""Offline BGP relationship inference and route leak scoring service.

Protocol: core routing inference service, version 1, revision 1.

Reads one JSON document from stdin, writes one JSON document to stdout:
either {"error":"invalid"}, {"error":"zero-partition"} or the full result
with link probabilities, peeling rounds and per-query route leak scoring.
"""
import json
import re
import sys
from fractions import Fraction
from itertools import product


class Invalid(Exception):
    """Any schema, bounds or structural violation of the input."""


# g(L, R) table: rows L, columns R, states 0=c2p 1=p2p 2=p2c.
GTAB = ((0, 0, 1), (1, 1, 2), (1, 1, 2))
ID_RE = re.compile(r"[A-Za-z0-9_.-]{1,64}")
UNIFORM = (Fraction(1, 3), Fraction(1, 3), Fraction(1, 3))
ASN_MAX = 4294967295


def is_asn(x):
    return type(x) is int and 1 <= x <= ASN_MAX


# --------------------------------------------------------------------------
# strict JSON parsing
# --------------------------------------------------------------------------

def strict_loads(text):
    def hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise Invalid()
            d[k] = v
        return d

    def bad(_x):
        raise Invalid()

    try:
        return json.loads(text, object_pairs_hook=hook,
                          parse_float=bad, parse_constant=bad)
    except Invalid:
        raise
    except Exception:
        raise Invalid()


# --------------------------------------------------------------------------
# validation
# --------------------------------------------------------------------------

def validate(data):
    if type(data) is not dict:
        raise Invalid()
    if set(data.keys()) != {"version", "ixps", "rib", "priors", "declared",
                            "order", "queries"}:
        raise Invalid()
    if type(data["version"]) is not int or data["version"] != 1:
        raise Invalid()

    ixl = data["ixps"]
    if type(ixl) is not list or len(ixl) > 1024:
        raise Invalid()
    ixps = set()
    for a in ixl:
        if not is_asn(a) or a in ixps:
            raise Invalid()
        ixps.add(a)

    ribl = data["rib"]
    if type(ribl) is not list or len(ribl) > 2000:
        raise Invalid()
    rib = []
    total = 0
    for rec in ribl:
        if type(rec) is not dict or set(rec.keys()) != {"path", "count"}:
            raise Invalid()
        p = rec["path"]
        c = rec["count"]
        if type(p) is not list or len(p) > 64:
            raise Invalid()
        for a in p:
            if not is_asn(a):
                raise Invalid()
        if type(c) is not int or not (1 <= c <= 1000000):
            raise Invalid()
        total += len(p)
        if total > 40000:
            raise Invalid()
        rib.append((p, c))

    prl = data["priors"]
    if type(prl) is not list or len(prl) > 2000:
        raise Invalid()
    priors = {}
    for rec in prl:
        if type(rec) is not dict or set(rec.keys()) != {"link", "weights"}:
            raise Invalid()
        link = rec["link"]
        wts = rec["weights"]
        if type(link) is not list or len(link) != 2:
            raise Invalid()
        u, v = link
        if not is_asn(u) or not is_asn(v) or u == v:
            raise Invalid()
        if type(wts) is not list or len(wts) != 3:
            raise Invalid()
        if any(type(x) is not int or not (0 <= x <= 1000000) for x in wts):
            raise Invalid()
        s = wts[0] + wts[1] + wts[2]
        if s <= 0:
            raise Invalid()
        key = (u, v) if u < v else (v, u)
        if key in priors:
            raise Invalid()
        if u < v:
            vec = (Fraction(wts[0], s), Fraction(wts[1], s), Fraction(wts[2], s))
        else:
            vec = (Fraction(wts[2], s), Fraction(wts[1], s), Fraction(wts[0], s))
        priors[key] = vec

    dcl = data["declared"]
    if type(dcl) is not list or len(dcl) > 2000:
        raise Invalid()
    declared = {}
    for rec in dcl:
        if type(rec) is not dict or set(rec.keys()) != {"link", "rel"}:
            raise Invalid()
        link = rec["link"]
        rel = rec["rel"]
        if type(link) is not list or len(link) != 2:
            raise Invalid()
        u, v = link
        if not is_asn(u) or not is_asn(v) or u == v:
            raise Invalid()
        if type(rel) is not str or rel not in ("c2p", "p2p", "p2c"):
            raise Invalid()
        key = (u, v) if u < v else (v, u)
        if key in declared:
            raise Invalid()
        slot = {"c2p": 0, "p2p": 1, "p2c": 2}[rel]
        if u > v:
            slot = 2 - slot
        vec = (Fraction(1) if 0 == slot else Fraction(0),
               Fraction(1) if 1 == slot else Fraction(0),
               Fraction(1) if 2 == slot else Fraction(0))
        declared[key] = vec

    odl = data["order"]
    if type(odl) is not list:
        raise Invalid()
    order_pairs = []
    seen = set()
    for rec in odl:
        if type(rec) is not list or len(rec) != 2:
            raise Invalid()
        u, v = rec
        if not is_asn(u) or not is_asn(v) or not u < v:
            raise Invalid()
        if (u, v) in seen:
            raise Invalid()
        seen.add((u, v))
        order_pairs.append((u, v))

    ql = data["queries"]
    if type(ql) is not list or len(ql) > 512:
        raise Invalid()
    queries = []
    ids = set()
    for rec in ql:
        if type(rec) is not dict or set(rec.keys()) != {"id", "path", "threshold"}:
            raise Invalid()
        qid = rec["id"]
        if type(qid) is not str or not ID_RE.fullmatch(qid):
            raise Invalid()
        if qid in ids:
            raise Invalid()
        ids.add(qid)
        p = rec["path"]
        if type(p) is not list or len(p) > 64:
            raise Invalid()
        for a in p:
            if not is_asn(a):
                raise Invalid()
        th = rec["threshold"]
        if type(th) is not list or len(th) != 2:
            raise Invalid()
        a, b = th
        if type(a) is not int or type(b) is not int:
            raise Invalid()
        if not (0 <= a <= b <= 1000000) or b < 1:
            raise Invalid()
        queries.append((qid, p, (a, b)))

    return ixps, rib, priors, declared, order_pairs, queries


# --------------------------------------------------------------------------
# path normalization and simultaneous peeling
# --------------------------------------------------------------------------

def normalize(path, ixps):
    out = []
    for a in path:
        if a in ixps:
            continue
        if out and out[-1] == a:
            continue
        out.append(a)
    return out


def peel(agg):
    """Simultaneous peripheral peeling. Returns (final_paths, rounds, links)."""
    all_links = set()
    for p in agg:
        for i in range(len(p) - 1):
            a, b = p[i], p[i + 1]
            all_links.add((a, b) if a < b else (b, a))
    rounds = {}
    paths = agg
    r = 0
    while True:
        info = {}
        for p in paths:
            n = len(p)
            first = p[0]
            last = p[-1]
            for i in range(n - 1):
                a, b = p[i], p[i + 1]
                key = (a, b) if a < b else (b, a)
                rec = info.get(key)
                if rec is None:
                    rec = [0, 0]
                    info[key] = rec
                u, v = key
                if first != u and last != u:
                    rec[0] = 1
                if first != v and last != v:
                    rec[1] = 1
        marked = set()
        for key, rec in info.items():
            if rec[0] == 0 or rec[1] == 0:
                marked.add(key)
        if not marked:
            break
        r += 1
        for key in marked:
            rounds[key] = r
        new = {}
        for p, c in paths.items():
            n = len(p)
            fa, fb = p[0], p[1]
            fkey = (fa, fb) if fa < fb else (fb, fa)
            s = 1 if fkey in marked else 0
            la, lb = p[n - 2], p[n - 1]
            lkey = (la, lb) if la < lb else (lb, la)
            e = n - 1 if lkey in marked else n
            if e - s >= 2:
                q = p[s:e]
                new[q] = new.get(q, 0) + c
        paths = new
    return paths, rounds, all_links


# --------------------------------------------------------------------------
# exact joint core inference (bounded treewidth variable elimination)
# --------------------------------------------------------------------------

def build_factors(final_paths, idx, m):
    """Build one phi_e factor per core link from final core path occurrences."""
    occs = [[] for _ in range(m)]
    for p, w in final_paths.items():
        n = len(p)
        for i in range(n - 1):
            a, b = p[i], p[i + 1]
            key = (a, b) if a < b else (b, a)
            vi = idx[key]
            forward = a < b
            if i == 0:
                L = None
            else:
                fa = p[i - 1]
                fkey = (fa, a) if fa < a else (a, fa)
                L = (idx[fkey], fa < a)
            if i + 2 >= n:
                R = None
            else:
                ba = p[i + 2]
                gkey = (b, ba) if b < ba else (ba, b)
                R = (idx[gkey], b < ba)
            occs[vi].append((w, forward, L, R))

    factors = []
    scopes = []
    for e in range(m):
        occ = occs[e]
        scope_set = {e}
        for (_w, _f, L, R) in occ:
            if L is not None:
                scope_set.add(L[0])
            if R is not None:
                scope_set.add(R[0])
        scope = sorted(scope_set)
        scopes.append(scope)
        k = len(scope)
        strides = [3 ** (k - 1 - j) for j in range(k)]
        pos = {}
        for j, v in enumerate(scope):
            pos[v] = j
        pe = pos[e]
        table = [0] * (3 ** k)
        for (w, fwd, L, R) in occ:
            ctx = []
            if L is not None:
                ctx.append(L)
            if R is not None:
                ctx.append(R)
            ctxset = set(c[0] for c in ctx)
            rest = [j for j in range(k) if j != pe and scope[j] not in ctxset]
            nctx = len(ctx)
            for states in product(range(3), repeat=nctx):
                Ls = 0
                if L is not None:
                    t = states[ctx.index(L)] if L in ctx else 0
                    Ls = t if L[1] else 2 - t
                Rs = 2
                if R is not None:
                    t = states[ctx.index(R)] if R in ctx else 0
                    Rs = t if R[1] else 2 - t
                g = GTAB[Ls][Rs]
                pref = g if fwd else 2 - g
                base = strides[pe] * pref
                for t in range(nctx):
                    base += strides[pos[ctx[t][0]]] * states[t]
                if not rest:
                    table[base] += w
                else:
                    for rst in product(range(3), repeat=len(rest)):
                        ii = base
                        for t in range(len(rest)):
                            ii += strides[rest[t]] * rst[t]
                        table[ii] += w
        factors.append((scope, table))
    return factors, scopes


def fmul(a, b):
    v1, t1 = a
    v2, t2 = b
    s1 = set(v1)
    s2 = set(v2)
    u = sorted(s1 | s2)
    ku = len(u)
    k1 = len(v1)
    k2 = len(v2)
    w1 = [0] * ku
    w2 = [0] * ku
    for j, v in enumerate(u):
        if v in s1:
            w1[j] = 3 ** (k1 - 1 - v1.index(v))
        if v in s2:
            w2[j] = 3 ** (k2 - 1 - v2.index(v))
    n = 3 ** ku
    res = [0] * n
    digits = [0] * ku
    i1 = 0
    i2 = 0
    for iu in range(n):
        res[iu] = t1[i1] * t2[i2]
        j = ku - 1
        while j >= 0:
            digits[j] += 1
            i1 += w1[j]
            i2 += w2[j]
            if digits[j] < 3:
                break
            digits[j] = 0
            i1 -= 3 * w1[j]
            i2 -= 3 * w2[j]
            j -= 1
    return (u, res)


def fsum(a, x):
    v, t = a
    k = len(v)
    j = v.index(x)
    stride = 3 ** (k - 1 - j)
    nv = v[:j] + v[j + 1:]
    nlen = stride
    nt = [0] * nlen
    for iu, val in enumerate(t):
        hi = iu // (stride * 3)
        lo = iu % stride
        nt[hi * stride + lo] += val
    return (nv, nt)


def eliminate(factors, order_idx, skip):
    """Eliminate every variable except `skip`; return remaining factor."""
    fs = list(factors)
    for x in order_idx:
        if x == skip:
            continue
        bucket = []
        rest = []
        for f in fs:
            if x in f[0]:
                bucket.append(f)
            else:
                rest.append(f)
        acc = bucket[0]
        for f in bucket[1:]:
            acc = fmul(acc, f)
        acc = fsum(acc, x)
        rest.append(acc)
        fs = rest
    out = ([], [1])
    for f in fs:
        out = fmul(out, f)
    return out


def check_width(scopes, order_idx, m):
    neigh = []
    for e in range(m):
        s = set(scopes[e])
        s.discard(e)
        neigh.append(s)
    for x in order_idx:
        cur = neigh[x]
        if len(cur) > 4:
            raise Invalid()
        cl = sorted(cur)
        for i in range(len(cl)):
            a = cl[i]
            for j in range(i + 1, len(cl)):
                b = cl[j]
                neigh[a].add(b)
                neigh[b].add(a)
        for y in cur:
            neigh[y].discard(x)
        neigh[x] = set()


# --------------------------------------------------------------------------
# main solver
# --------------------------------------------------------------------------

def solve(raw):
    if len(raw) > 4194304:
        raise Invalid()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise Invalid()
    data = strict_loads(text)
    ixps, rib, priors, declared, order_pairs, queries = validate(data)

    # Normalize and aggregate accepted RIB paths.
    agg = {}
    for p, c in rib:
        q = normalize(p, ixps)
        if len(q) < 2 or len(set(q)) != len(q):
            continue
        t = tuple(q)
        agg[t] = agg.get(t, 0) + c

    final, rounds, all_links = peel(agg)
    if len(all_links) > 4096:
        raise Invalid()

    core_links = sorted(k for k in all_links if k not in rounds)
    if len(core_links) > 64:
        raise Invalid()

    if len(order_pairs) != len(core_links) or set(order_pairs) != set(core_links):
        raise Invalid()

    idx = {}
    for i, e in enumerate(core_links):
        idx[e] = i
    m = len(core_links)
    order_idx = [idx[pair] for pair in order_pairs]

    marginals = {}
    if m > 0:
        factors, scopes = build_factors(final, idx, m)
        check_width(scopes, order_idx, m)
        zfac = eliminate(factors, order_idx, -1)
        Z = zfac[1][0]
        if Z == 0:
            return {"error": "zero-partition"}
        for e in range(m):
            f = eliminate(factors, order_idx, e)
            vals = f[1]
            marginals[core_links[e]] = (Fraction(vals[0], Z),
                                        Fraction(vals[1], Z),
                                        Fraction(vals[2], Z))

    # Links output.
    out_links = []
    for key in sorted(all_links):
        r = rounds.get(key, 0)
        if r == 0:
            prob = marginals[key]
        else:
            prob = priors.get(key, UNIFORM)
        out_links.append({"link": [key[0], key[1]], "round": r,
                          "prob": [float(prob[0]), float(prob[1]), float(prob[2])]})

    # Queries.
    out_queries = []
    for qid, p, th in queries:
        qn = normalize(p, ixps)
        if len(set(qn)) != len(qn):
            out_queries.append({"id": qid, "path": qn, "status": "loop",
                                "score": None, "full": None, "witness": None,
                                "leaked": None})
            continue
        if len(qn) < 3:
            out_queries.append({"id": qid, "path": qn, "status": "ok",
                                "score": 1.0, "full": 1.0, "witness": None,
                                "leaked": False})
            continue
        probs = []
        for a, b in zip(qn, qn[1:]):
            key = (a, b) if a < b else (b, a)
            if key in declared:
                vec = declared[key]
            elif key in marginals:
                vec = marginals[key]
            elif key in priors:
                vec = priors[key]
            else:
                vec = UNIFORM
            if a > b:
                vec = (vec[2], vec[1], vec[0])
            probs.append(vec)
        triples = []
        for i in range(len(probs) - 1):
            U = probs[i][0]
            D = probs[i + 1][2]
            triples.append(U + D - U * D)
        score = triples[0]
        witness = 0
        for i in range(1, len(triples)):
            if triples[i] < score:
                score = triples[i]
                witness = i
        up = Fraction(1)
        peer = Fraction(0)
        down = Fraction(0)
        for vec in probs:
            a, b, c = vec
            up, peer, down = up * a, up * b, (up + peer + down) * c
        full = up + peer + down
        leaked = score < Fraction(th[0], th[1])
        out_queries.append({"id": qid, "path": qn, "status": "ok",
                            "score": float(score), "full": float(full),
                            "witness": witness, "leaked": leaked})

    return {"version": 1, "links": out_links, "queries": out_queries}


def main():
    raw = sys.stdin.buffer.read(4194305)
    try:
        answer = solve(raw)
    except Invalid:
        answer = {"error": "invalid"}
    sys.stdout.write(json.dumps(answer, allow_nan=False) + "\n")


if __name__ == "__main__":
    main()
